@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=IM+Fell+English:ital@0;1&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#101513;--panel:#171e1a;--panel2:#1b231f;--line:#2a342e;--text:#e8e8d9;--muted:#929b90;--dim:#68746b;--gold:#d5b875;--gold2:#e8ca85;--green:#829b74;--serif:'IM Fell English',Georgia,serif;--sans:'DM Sans',sans-serif;--display:'Manrope',sans-serif}
