d small{display:block}.world-card strong{font:600 12px var(--display)}.world-card small{font-size:10px;color:var(--muted);margin-top:3px}.live-dot{height:6px;width:6px;border-radius:50%;background:#90a578;margin-left:auto;box-shadow:0 0 8px #90a578}.world-note{font:italic 13px/1.6 var(--serif);color:#90988a;padding:15px 10px;max-width:190px}.side-bottom{margin-top:auto;border-top:1px solid #2a322d;padding:17px 4px 0;display:flex;align-items:center;gap:10px}.avatar-mini{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;color:var(--gold);background:#333125;border:1px solid #514a35}.player-meta{min-width:0}.player-meta b,.player-meta small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:130px}.player-meta b{font-size:11px}.player-meta small{font-size:10px;color:var(--muted);margin-top:3px}.icon-button{width:30px;height:30px;border:1px solid #354038;border-radius:5px;background:#1a221d;color:#a7ad9e;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--gold);color:var(--gold)}.side-bottom .icon-button{margin-left:auto;background:transparent;border:0}.main-area{flex:1;min-width:0}.topbar{height:68px;border-bottom:1px solid #252d28;padding:0 38px;display:flex;align-items:center;justify-content:space-between}.breadcrumb{font:700 9px var(--display);letter-spacing:1.6px;color:#9aa296;display:flex;gap:10px;align-items:center}.breadcrumb b{color:#736d4b;font-size:14px}.breadcrumb span:last-child{color:#d1ceb9}.top-actions{display:flex;align-items:center;gap:17px}.date-chip{font:600 9px var(--display);letter-spacing:1.15px;color:#9ea497;display:flex;gap:8px;align-items:center}.date-chip span:first-child{color:var(--gold);font-size:14px}.save-button{border:1px solid #444335;background:#26281f;color:#d4c38f;border-radius:4px;height:34px;padding:0 12px;font-size:10px;letter-spacing:.25px;cursor:pointer}.save-button span{font-size:15px;margin-right:6px}.save-button:hover{background:#343126;border-color:#85784e}.mobile-menu{display:none;background:none;border:0;font-size:20px}.game-layout{max-width:1500px;margin:auto;padding:35px 38px 40px;display:grid;grid-template-columns:minmax(440px,1fr) 315px;gap:39px}.story-column{min-width:0;max-width:840px}.scene-head{display:flex;align-items:flex-start;justify-content:space-between;margin:1px 0 21px}.scene-head h1{font:400 36px/1.1 var(--serif);letter-spacing:-.3px;margin:9px 0 0;color:#e8e6d7}.scene-head h1 em{color:var(--gold2);font-weight:400}.scene-actions{display:flex;gap:7px}.scene-actions .icon-button{background:#171e1a}.scene-art{height:218px;border:1px solid #414334;border-radius:6px;position:relative;overflow:hidden;background:linear-gradient(180deg,#26383a 0%,#314442 42%,#55634c 71%,#26372b 100%);box-shadow:0 12px 30px #060b0838}.scene-art:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#17211e3b,#11191500 40%,#1017154d),linear-gradient(0deg,#121816bb,transparent 36%);z-index:2}.art-sun{position:absolute;width:60px;height:60px;border-radius:50%;background:#d6bd7e;top:44px;left:62%;box-shadow:0 0 36px 10px #d4bd7d55}.art-moon{display:none}.art-mountain{position:absolute;bottom:40px;clip-path:polygon(0 100%,45% 0,100% 100%);width:60%;height:150px;background:#36443d}.mountain-back{left:10%;height:161px;width:53%;background:#4b5a4d;clip-path:polygon(0 100%,37% 10%,48% 39%,68% 0,100% 100%)}.mountain-front{right:-2%;height:130px;width:59%;background:#303e34;clip-path:polygon(0 100%,33% 0,46% 41%,64% 11%,100% 100%)}.art-forest{position:absolute;inset:auto 0 22px;height:94px;background:linear-gradient(165deg,transparent 0 21%,#1d3028 21.3% 40%,transparent 40.3%),linear-gradient(15deg,transparent 0 32%,#24382d 32.3% 59%,transparent 59.3%),linear-gradient(180deg,transparent,#192a21 60%);opacity:.9}.art-road{position:absolute;bottom:-45px;left:43%;width:17%;height:133px;background:#9c9069;clip-path:polygon(42% 0,58% 0,100% 100%,0 100%);opacity:.55;filter:blur(1px)}.art-caption{position:absolute;z-index: