op:19%}.label-three{left:4%;top:70%}.map-compass{position:absolute;z-index:2;right:9px;top:8px;font:700 7px var(--display);text-align:center;color:#929b87}.map-compass b{font-size:13px;color:#d4c17e}.location-footer{display:flex;align-items:center;justify-content:space-between;padding-top:10px}.location-footer strong,.location-footer small{display:block}.location-footer strong{font:500 12px var(--display);color:#dedecf}.location-footer small{font-size:9px;color:#899286;margin-top:3px}.weather-icon{font-size:18px;color:#9da896}.world-pulse{padding:14px}.live-label{font-size:8px;letter-spacing:.8px;color:#90a57c}.live-label i{display:inline-block;width:5px;height:5px;background:#94a780;border-radius:50%;margin-right:4px;box-shadow:0 0 6px #94a780}.pulse-entry{display:flex;gap:10px;margin:13px 0 12px;align-items:flex-start}.pulse-icon{width:25px;height:25px;border:1px solid #464638;border-radius:50%;display:grid;place-items:center;color:#c5b16b;flex-shrink:0}.pulse-entry b{font:600 11px var(--display);color:#d8d8c8}.pulse-entry p{font-size:10px;line-height:1.5;color:#8e978a;margin:4px 0 0}.subtle-link{display:block;border:0;border-top:1px solid #2b342e;background:transparent;color:#b8a875;width:100%;text-align:left;padding:10px 0 0;font-size:10px;cursor:pointer}.subtle-link span{float:right;font-size:14px}.rail-footer{margin-top:auto;padding-top:12px;display:flex;justify-content:space-between;color:#5e685f;font:700 7px var(--display);letter-spacing:.8px}.hidden{display:none!important}.toast{position:fixed;z-index:20;right:24px;bottom:22px;padding:12px 17px;border:1px solid #665c3f;background:#20251d;border-radius:5px;color:#e0d19a;font-size:12px;box-shadow:0 10px 35px #0008;opacity:0;transform:translateY(12px);transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translateY(0)}.modal-backdrop{position:fixed;z-index:15;inset:0;background:#050806bb;display:grid;place-items:center;padding:20px;backdrop-filter:blur(3px)}.modal{position:relative;width:min(620px,100%);max-height:85vh;overflow:auto;border:1px solid #55503a;background:#171e1a;border-radius:8px;padding:25px;box-shadow:0 25px 80px #0009}.modal-close{position:absolute;right:14px;top:11px;border:0;background:none;color:#a8ae9e;font-size:24px;cursor:pointer}.modal h2{font:400 27px var(--serif);margin:0 35px 7px 0;color:#e7e3d2}.modal .modal-sub{font-size:11px;color:#91998d;margin:0 0 20px}.sheet-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:15px 0}.sheet-stat,.sheet-block{border:1px solid #343d34;background:#1c231e;border-radius:4px;padding:11px}.sheet-stat small,.sheet-block small{display:block;color:#899386;font:700 8px var(--display);letter-spacing:1px}.sheet-stat strong{font:600 17px var(--display);color:#e4e0ce;display:block;margin-top:5px}.sheet-block{margin:9px 0}.sheet-block p{margin:6px 0 0;color:#c0c3b4;font-size:11px;line-height:1.65}.modal-list{padding:0;margin:0;list-style:none}.modal-list li{padding:12px 0;border-bottom:1px solid #303830;color:#d5d7c8;font-size:12px}.modal-list li small{display:block;color:#899386;font-size:10px;margin-top:4px}.combat-banner{border:1px solid #674b37;background:#2c211c;border-radius:5px;padding:12px;color:#e1b99a;font-size:11px;margin:12px 0}.roll-log{font:11px/1.8 monospace;background:#111713;border:1px solid #30382f;padding:10px;color:#c7c9b8;border-radius:4px}
