const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const steps=[
 {key:'name',title:'What is your name?',help:'Every road begins with someone choosing to take it. What should the world call you?',type:'text',placeholder:'Your character’s name'},
 {key:'ancestry',title:'What is your ancestry?',help:'Ancestry shapes how others see you—and how you see the world.',options:[['Human','Adaptable, ambitious, and at home almost anywhere.'],['Elf','Long-lived, keen-sensed, and attuned to old magic.'],['Dwarf','Stout, steadfast, and raised among stone or steel.'],['Halfling','Small, resourceful, and often luckier than they ought to be.'],['Orc-blooded','Powerful, resilient, and never easily underestimated.'],['Tiefling','Marked by an ancient infernal legacy; no two marks alike.']]},
 {key:'class',title:'What path have you mastered?',help:'Your class describes training and talents, not who you must become.',options:[['Fighter','A disciplined warrior; reliable with weapons and armor.'],['Rogue','A scout and opportunist; excels at stealth and precision.'],['Wizard','A scholar of arcane magic; powerful, but prepared spells are limited.'],['Cleric','A divine conduit; protective magic and martial resolve.'],['Ranger','A hunter of wild places; survivalist and ranged combatant.'],['Bard','A versatile performer; words, wit, and a touch of magic.']]},
 {key:'background',title:'Where did you come from?',help:'Your former life leaves contacts, instincts, and unfinished business.',options:[['Wayfarer','You know how to find shelter where maps end.'],['Soldier','You served under a banner—and remember what it cost.'],['Scholar','You spent years among books, relics, or forbidden questions.'],['Outlander','The wilderness raised you more than any town did.'],['Artisan','You learned a craft whose value travels farther than you.'],['Criminal','You know the quiet doors and the price of silence.']]},
 {key:'personality',title:'What guides your choices?',help:'A compass, not a cage. Your outlook can change as the world presses in.',options:[['Kind-hearted','You look for the person behind the problem.'],['Pragmatic','You weigh consequences before ideals.'],['Curious','A mystery left unopened feels like a dare.'],['Defiant','You resist being told what cannot be done.'],['Reserved','Trust is earned, and silence has its uses.'],['Idealistic','You believe the world can be better—and act accordingly.']]},
 {key:'difficulty',title:'How dangerous should the road be?',help:'This adjusts encounter pressure, resource scarcity, and consequences.',options:[['Story','Forgiving danger; narrative and discovery take the lead.'],['Adventurer','Balanced exploration, tactical choices, and risk.'],['Veteran','Harder foes, scarce supplies, and sharper consequences.'],['Hardcore','Severe danger. Death is permanent; no safety net.']]},
