const state={step:0,answers:{},hero:null,started:false,location:'The Unwritten Road',node:'road',time:1,day:1,weather:'Low clouds, a wind from the west',gold:18,xp:0,hp:0,maxHp:0,quests:[],log:[],inventory:[],companions:[],factions:{},visited:['The Unwritten Road'],combat:null};
const scenes={road:{name:'The Unwritten Road',detail:'The Shattered Marches · Frontier',title:'Where the old road ends',eyebrow:'THE SHATTERED MARCHES',body:'The road is a pale scar through the heather, its old paving stones split by roots. Somewhere beyond the ridge, a bell rings once—then falls quiet. A weather-beaten milestone points north to Morrowfen and east toward the distant black teeth of the Ashen Crown.\n\nAt the roadside, a handcart has tipped into a ditch. Its owner, a broad-shouldered woman in a moss-green cloak, is trying to free one wheel before the rain arrives. She glances up as you approach, measuring you without quite deciding what she sees.',choices:[['Offer to help with the cart','A small kindness may earn a little trust.','help'],['Ask about the bell','Find out who—or what—rang it.','bell'],['Continue toward Morrowfen','A village lies north, beneath the rain-heavy sky.','village'],['Inspect the milestone','The old carvings may reveal more than directions.','stone']]},
 village:{name:'Morrowfen',detail:'The Shattered Marches · Hamlet',title:'A town holding its breath',eyebrow:'MORROWFEN · NORTH ROAD',body:'Morrowfen gathers around a millpond the color of pewter. Smoke lies low over thatched roofs. Nobody has barred the road, but the people you pass stop speaking as you draw near. At the well, a child turns a little silver bell over in her hands; it is wrapped in blue thread.\n\nThe cart-woman’s name is Sella Venn. She mentioned her brother went looking for the source of the bell and did not return. The inn glows amber at the end of the lane; across from it, a shuttered shrine bears a fresh mark in chalk.',choices:[['Speak with Sella at the inn','She may know more about her brother.','sella'],['Ask the child about the silver bell','The child watches you from beside the well.','child'],['Examine the shuttered shrine','The chalk mark is recent.','shrine'],['Leave town and follow the northern trail','The trail bends toward a stand of dark pines.','trail']]},
 forest:{name:'Bellweather Wood',detail:'North of Morrowfen · Old forest',title:'A silence between the trees',eyebrow:'BELLWEATHER WOOD',body:'The pines crowd close enough to swallow the sky. A narrow trail descends into a damp hollow, where scraps of blue thread snag on the thorns. Near a leaning stone, you find a boot-print pressed into the mud beside a fresh set of claw marks. Whatever made them was heavy—and moving quickly.\n\nA faint metallic chime comes from deeper in the wood. In the silence after it, something shifts behind the trees.',choices:[['Follow the chime carefully','Stay alert; the ground is slick with roots.','chime'],['Track the boot-prints','The tracks may lead to Sella’s missing brother.','tracks'],['Return to Morrowfen','The village is safer, for now.','village']]},
 ruin:{name:'The Bell Vault',detail:'Bellweather Wood · Ruined shrine',title:'The sound beneath the stone',eyebrow:'A PLACE LEFT OFF THE MAP',body:'A half-buried stair descends beneath a ruin clasped in ivy. The air below is warmer than the rain above, carrying the scent of beeswax and something sharp, like struck flint. A bronze bell hangs in a narrow chamber—but its clapper has been removed. Blue thread is tied around its handle.\n\nA figure stands in the far archway, one hand raised to shield a lantern. “If you came for the bell,” they say, “you’re already late.”',choices:[['Ask who they are','A calm voice may reveal more than a drawn blade.','talk'],['Study the bell and chamber','Look for a mechanism or signs of magic.','inspect'],['Approach the figure cautiously','You can close the distance without drawing a weapon.','approach'],['Retreat into the wood','Some answers can wait.','forest']]}};
const line=(text)=>{state.log.unshift(text);state.log=state.log.slice(0,30)};
function renderStep(){const s=steps[state.step],card=$('#creation-card');card.innerHTML=`<div class="step-top"><span class="step-caption">CHARACTER CREATION</span><span class="step-index">${String(state.step+1).padStart(2,'0')} / ${steps.length}</span></div><div class="step-track">${steps.map((_,i)=>`<i class="${i<=state.step?'done':''}"></i>`).join('')}</div><h2>${s.title}</h2><p class="step-help">${s.help}</p><div id="step-content"></div><div class="step-controls">${state.step?'<button class="back-btn" id="back-btn">← Back</button>':'<span></span>'}<button class="next-btn" id="next-btn">${state.step===steps.length-1?'Create character':'Continue →'}</button></div>`;
 const content=$('#step-content'); if(s.type==='text'){content.innerHTML=`<label class="field-label" for="step-input">NAME</label><input id="step-input" class="text-field" maxlength="24" placeholder="${s.placeholder}" value="${esc(state.answers[s.key]||'')}" autofocus>`;$('#step-input').addEventListener('input',e=>state.answers[s.key]=e.target.value.trim())} else {content.innerHTML=`<div class="choice-grid">${s.options.map(([name,desc])=>`<label class="option-card ${state.answers[s.key]===name?'selected':''}"><input type="radio" name="choice" value="${esc(name)}" ${state.answers[s.key]===name?'checked':''}><b>${esc(name)}</b><small>${esc(desc)}</small></label>`).join('')}</div>`;$$('.option-card').forEach(el=>el.addEventListener('click',()=>{$$('.option-card').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');state.answers[s.key]=el.querySelector('input').value}))}
 $('#next-btn').onclick=()=>{if(!state.answers[s.key]){toast(s.type==='text'?'Please enter a name to continue.':'Choose an option to continue.');return}if(state.step<steps.length-1){state.step++;renderStep()}else createHero()};if(state.step)$('#back-btn').onclick=()=>{state.step--;renderStep()};if(s.type==='text')$('#step-input').focus();}
function createHero(){const a=state.answers, classBase={Fighter:[12,10,12,8,10,10],Rogue:[8,14,10,10,12,12],Wizard:[8,12,10,14,12,10],Cleric:[12,8,12,10,14,10],Ranger:[10,14,12,10,14,8],Bard:[8,12,10,12,10,14]}[a.class]||[10,10,10,10,10,10];const labels=['STR','DEX','CON','INT','WIS','CHA'];const attrs={};labels.forEach((k,i)=>attrs[k]=classBase[i]);state.hero={name:a.name,ancestry:a.ancestry,class:a.class,background:a.background,personality:a.personality,difficulty:a.difficulty,party:a.party,campaign:a.campaign,attrs,level:1,proficiency:2};state.maxHp=({Fighter:12,Rogue:10,Wizard:8,Cleric:10,Ranger:11,Bard:9}[a.class]||10)+Math.floor((attrs.CON-10)/2);state.hp=state.maxHp;state.gold=18;state.inventory=[a.class==='Fighter'?'Iron longsword':a.class==='Rogue'?'Hunting bow':a.class==='Wizard'?'Ash wand':a.class==='Cleric'?'Oak mace':a.class==='Ranger'?'Recurve bow':'Traveling lute','Worn leather armor','Rations ×2','Waterskin'];state.step=8;renderConfirm();updateUI()}
function renderConfirm(){const h=state.hero,c=$('#creation-card');$('#scene-title').innerHTML='A name takes shape.<br><em>The road can wait.</em>';$('#scene-eyebrow').textContent='CHARACTER READY';$('#story-body').innerHTML=`<p class="lead">${esc(h.name)}. A name the road has not heard before.</p><p>In the Shattered Marches, names are carried on wind and rumor. Yours begins with a past, a chosen path, and no promise of what comes next. The world is ready; the first adventure will begin only when you confirm your character.</p>`;c.innerHTML=`<div class="step-top"><span class="step-caption">YOUR CHARACTER</span><span class="step-index">LEVEL 1 · ${esc(h.class.toUpperCase())}</span></div><h2>${esc(h.name)}, ${esc(h.ancestry)} ${esc(h.class)}</h2><p class="step-help">${esc(h.background)} · ${esc(h.personality)} · ${esc(h.difficulty)} difficulty · ${esc(h.campaign)}</p><div class="attribute-row" style="padding:12px 0;border-top:1px solid #303830">${Object.entries(h.attrs).map(([k,v])=>`<span><b>${k}</b>${v} (${mod(v)})</span>`).join('')}</div><div class="step-controls"><button class="back-btn" id="edit-hero">← Edit character</button><button class="next-btn" id="confirm-hero">Confirm & begin adventure →</button></div>`;$('#edit-hero').onclick=()=>{state.step=7;renderStep()};$('#confirm-hero').onclick=beginAdventure;}
function beginAdventure(){state.started=true;state.node='road';state.location='The Unwritten Road';state.quests=[{name:'The Silent Bell',description:'Discover why a bell rang beyond the ridge—and what happened to Sella Venn’s brother.',status:'Active'}];line('The journey began on the Unwritten Road.');$('#creation-card').classList.add('hidden');$('#story-body').innerHTML='';showScene('road');updateUI();toast('Your campaign has begun. Good luck, '+state.hero.name+'.')}
function showScene(id,custom){state.node=id;const s=scenes[id]||scenes.road;state.location=s.name;$('#scene-eyebrow').textContent=s.eyebrow;$('#scene-title').textContent=s.title;$('#top-location').textContent=s.name.toUpperCase();$('#location-name').textContent=s.name;$('#map-current').textContent=s.name;$('#location-detail').textContent=s.detail;$('#story-body').innerHTML=(custom||s.body).split('\n\n').map((p,i)=>`<p ${i===0?'class="lead"':''}>${esc(p)}</p>`).join('');const box=$('#decision-area');box.classList.remove('hidden');$('#choice-list').innerHTML=s.choices.map(([title,desc,act],i)=>`<button class="story-choice" data-act="${act}"><span class="choice-marker">${String.fromCharCode(65+i)}</span><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`).join('');$$('.story-choice').forEach(b=>b.onclick=()=>act(b.dataset.act));if(!state.visited.includes(s.name))state.visited.push(s.name);updateUI()}
function rollCheck(skill,ability,dc,bonus=0){const raw=Math.floor(Math.random()*20)+1, modv=Math.floor((state.hero.attrs[ability]-10)/2), total=raw+modv+bonus;return {raw,modv,bonus,total,dc,success:total>=dc,skill}}
function rollText(r){return `${r.skill}: d20 (${r.raw}) ${r.modv>=0?'+':''}${r.modv} ability ${r.bonus?`+ ${r.bonus} proficiency`:''} = ${r.total} vs DC ${r.dc} · ${r.success?'Success':'Failure'} (pseudorandom)`}
function act(key){if(!state.started)return;tick();let text='',check=null;
 switch(key){case'help':check=rollCheck('Athletics','STR',12,state.hero.class==='Fighter'?2:0);text=check.success?'The cart wheel breaks free with a wet pop. Sella wipes her hands and gives you a grateful, searching look. “You’ve the look of someone who can mind their own business. Usually a useful talent.” She tells you her brother vanished near Bellweather Wood.':'The wheel slips from your grip and sinks deeper into the ditch. Sella exhales, then shakes her head. “No matter. I’ll find a lever.” Her brother went missing near Bellweather Wood.';if(check.success)state.gold+=2;break;
 case'bell':check=rollCheck('Insight','WIS',12);text=check.success?'The bell sounded from the north ridge, Sella says—and her eyes flick to the trees. The village bell has been silent for years. “My brother went to look. I should have stopped him.”':'Sella only knows that the sound came from the north ridge. Her brother followed it three nights ago and never returned.';break;
 case'village':showScene('village');return;
 case'stone':check=rollCheck('Investigation','INT',13);text=check.success?'You brush lichen from the milestone. Someone carved a tiny bell beneath the old directions, then scratched out the line pointing north. The cut is fresh.':'Rain has softened the old carvings. You can make out Morrowfen to the north, and a faded warning: “WHEN THE BELL IS STILL.”';break;
 case'child':check=rollCheck('Persuasion','CHA',12);text=check.success?'The child holds out the bell. “It was in the reeds. It rang all by itself.” Inside its hollow handle is a strip of blue thread.':'The child clutches the bell close. “It’s mine,” she insists, and bolts into a nearby cottage.';break;
 case'sella':text='Sella has not returned to the inn. The keeper says she took a lantern and headed north, toward the wood. A half-finished mug cools beside the door.';break;
 case'shrine':check=rollCheck('Investigation','INT',14);text=check.success?'The chalk is a warding sign, hastily copied from the old shrine door. Behind the loose stone you find a wax-sealed note: “Do not answer the second ringing.”':'The chalk symbol is unfamiliar, but deliberate. Beneath the shrine door, something has recently dragged a line through the dust.';break;
 case'trail':case'tracks':showScene('forest');return;
 case'chime':case'approach':case'talk':if(key==='approach'&&state.combat){combatTurn('attack');return}check=rollCheck('Perception','WIS',13);if(check.success){text='You step into a clearing and find a narrow stair descending beneath a tangle of roots. The chime comes from below. A bronze glimmer moves in the dark.';state.xp+=15;state.pulse='A way beneath the roots';state.pulseCopy='Something is ringing below Bellweather Wood.';showScene('forest',text+'\n\nA narrow stair descends into a buried chamber.');$('#choice-list').innerHTML=`<button class="story-choice" data-act="descend"><span class="choice-marker">A</span><span><strong>Descend into the buried chamber</strong><small>The bell is close now. The steps are slick.</small></span></button><button class="story-choice" data-act="village"><span class="choice-marker">B</span><span><strong>Return to Morrowfen</strong><small>Tell the villagers what you found.</small></span></button>`;$$('.story-choice').forEach(b=>b.onclick=()=>act(b.dataset.act));return}else{text='A branch cracks underfoot. From the shadows, a gaunt marsh-wolf darts at you, hackles raised.';startCombat('Marsh wolf',12,4);showScene('forest',text);return}
 case'descend':showScene('ruin');return;
 case'inspect':check=rollCheck('Arcana','INT',14,state.hero.class==='Wizard'?2:0);text=check.success?'The bell is not enchanted—it is a ward. A hairline crack runs through the stone below it, and cold air rises from somewhere deeper. The figure watches, lantern held low.':'The bell is old bronze, cold despite the warm chamber. The figure shifts their weight. “Don’t touch it.”';break;
 case'approach':text='You move closer. The figure lowers the lantern: a young man, mud-spattered and exhausted, with the same blue thread at his wrist. “Sella sent you?”';break;
 case'talk':text='“My name is Tovan. I rang it once, by mistake. Something below answered.” He looks at the bell. “I came back to keep anyone else from making the same mistake.”';break;
 case'attack':startCombat('Vault sentinel',14,8);return;
 default:text='The moment passes, and the world keeps its own time.';}
 if(check){line(rollText(check));showRollToast(check)}line(text);state.pulse='The Marches remember';state.pulseCopy=text.slice(0,90)+(text.length>90?'…':'');showScene(state.node,text);updateUI()}
function startCombat(name,ac,enemyHp){state.combat={name,ac,hp:enemyHp,max:enemyHp,turn:1};const r=rollCheck('Initiative','DEX');line('Initiative: '+r.total+' (pseudorandom).');toast(`Combat begins — initiative ${r.total}.`);$('#pulse-title').textContent='Danger in the wood';$('#pulse-copy').textContent=`A ${name.toLowerCase()} blocks your path.`;showCombat()}
function showCombat(){const c=state.combat;if(!c)return;$('#scene-eyebrow').textContent='COMBAT · ROUND '+c.turn;$('#scene-title').innerHTML='A dangerous<br><em>encounter.</em>';$('#story-body').innerHTML=`<div class="combat-banner"><b>${esc(c.name)}</b> · Hostile · AC ${c.ac}<br>It moves between you and the path. Its condition: ${c.hp>c.max*.65?'unhurt':c.hp>c.max*.3?'wounded':'badly wounded'}.</div><p>Initiative is set. You have movement and one action. Decide quickly; the creature is watching for an opening.</p>`;$('#choice-list').innerHTML=`<button class="story-choice" data-combat="attack"><span class="choice-marker">⚔</span><span><strong>Attack</strong><small>Strike with your equipped weapon.</small></span></button><button class="story-choice" data-combat="dodge"><span class="choice-marker">◌</span><span><strong>Dodge and reposition</strong><small>Give up an attack to protect yourself.</small></span></button><button class="story-choice" data-combat="flee"><span class="choice-marker">↗</span><span><strong>Disengage and flee</strong><small>Retreat toward cover.</small></span></button>`;$$('[data-combat]').forEach(b=>b.onclick=()=>combatTurn(b.dataset.combat));$('#decision-area').classList.remove('hidden')}
function combatTurn(action){let c=state.combat;if(!c)return;if(action==='flee'){const r=rollCheck('Escape','DEX',12);line(rollText(r));if(r.success){state.combat=null;state.hp=Math.max(1,state.hp-1);line('You escape, taking a glancing blow.');showScene(state.node,'You break away and regain the trail, breathing hard. The threat remains behind you.')}else{enemyAttack();showCombat()}return}if(action==='attack'){const ability=state.hero.class==='Fighter'||state.hero.class==='Cleric'?'STR':'DEX',r=rollCheck('Weapon attack',ability,c.ac,state.hero.class==='Fighter'?2:0);line(rollText(r));if(r.success){let damage=Math.floor(Math.random()*6)+1+Math.max(0,r.modv);c.hp-=damage;line(`Your strike deals ${damage} damage.`);if(c.hp<=0){state.combat=null;state.xp+=40;state.gold+=4;line(`${c.name} falls. You gain 40 XP and find 4 gp.`);state.pulse='A threat has fallen';state.pulseCopy='The wood is quiet again—for the moment.';showScene(state.node,'The creature collapses, its breath shuddering out into the wet leaves. The path is clear. You gather 4 gp from a tangled satchel nearby.');updateUI();return}}}else line('You brace and watch the creature, making yourself a harder target.');enemyAttack();c.turn++;showCombat();updateUI()}
function enemyAttack(){const c=state.combat;if(!c)return;const d=Math.floor(Math.random()*5)+1;state.hp=Math.max(0,state.hp-d);line(`${c.name} attacks: pseudorandom d20; it deals ${d} damage. (You: ${state.hp}/${state.maxHp} HP)`);if(state.hp<=0){state.combat=null;$('#scene-title').innerHTML='The road grows<br><em>quiet.</em>';$('#story-body').innerHTML='<div class="combat-banner">You fall unconscious. This campaign uses simplified death saves. Choose /rest only after someone reaches you, or reload your last save. Your choices have consequences.</div>';$('#choice-list').innerHTML=`<button class="story-choice" id="last-save"><span class="choice-marker">↶</span><span><strong>Load your last save</strong><small>Campaign state saved in this browser.</small></span></button>`;$('#last-save').onclick=loadGame;$('#decision-area').classList.remove('hidden');toast('You have fallen. Load a save to continue.')}else showRollToast({skill:'Enemy attack',raw:'—',modv:0,bonus:0,total:'—',dc:'your AC',success:false})}
function submitAction(text){text=text.trim();if(!text)return;if(text.startsWith('/')){command(text);$('#action-input').value='';return}if(!state.started){toast('Finish character creation first.');return}tick();let ability='CHA',skill='Persuasion',dc=14;if(/sneak|hide|steal|quiet|shadow/i.test(text)){ability='DEX';skill='Stealth';dc=14}else if(/search|inspect|look|study|examine|investigate/i.test(text)){ability='INT';skill='Investigation';dc=13}else if(/climb|lift|break|force|push|jump/i.test(text)){ability='STR';skill='Athletics';dc=13}else if(/track|listen|notice|watch|survive/i.test(text)){ability='WIS';skill='Perception';dc=13}const r=rollCheck(skill,ability,dc,state.hero.background==='Scholar'&&ability==='INT'?2:0);line(rollText(r));let result=r.success?'Your approach earns a response, though not the whole answer.':'Your attempt draws attention, but the result is not what you hoped for.';if(/attack|fight|strike/i.test(text)){startCombat('Roadside attacker',13,8);return}if(/leave|travel|go to morrowfen|north/i.test(text)){showScene('village');return}if(/wood|forest|trail/i.test(text)){showScene('forest');return}if(/rest|sleep/i.test(text)){if(state.hp===state.maxHp){result='You are already at full vitality.'}else{state.hp=Math.min(state.maxHp,state.hp+Math.ceil(state.maxHp/2));result='You take a brief rest in a sheltered spot and recover some vitality. The passing hours will not wait.'}}line(result);showRollToast(r);showScene(state.node,result);updateUI()}
function tick(){state.time++;if(state.time>5){state.time=1;state.day++}$('#top-time').textContent=`FIRST THAW · DAY ${state.day} · ${['DAWN','MORNING','MIDDAY','AFTERNOON','DUSK'][state.time-1]}`}
function updateUI(){if(!state.hero)return;const h=state.hero;$('#sidebar-name').textContent=h.name;$('#sidebar-class').textContent=`Level ${h.level} · ${h.class}`;$('#hero-name').textContent=h.name;$('#hero-subtitle').textContent=`${h.ancestry} ${h.class} · ${h.background}`;$('#portrait').innerHTML=(h.class==='Wizard'?'✧':h.class==='Ranger'?'❧':'✦')+`<span class="portrait-level">${h.level}</span>`;$('#hp-value').innerHTML=`${state.hp} <i>/ ${state.maxHp}</i>`;$('#hp-bar').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;$('#ac-value').textContent=h.class==='Fighter'||h.class==='Cleric'?'16':'13';$('#gold-value').textContent=state.gold;$('#attribute-row').innerHTML=Object.entries(h.attrs).map(([k,v])=>`<span><b>${k}</b>${v>=10?'+':''}${mod(v)}</span>`).join('');$('#xp-label').textContent=`${state.xp} / 300 XP`;$('#xp-bar').style.width=Math.min(100,state.xp/3)+'%';$('#quest-count').textContent=state.quests.filter(q=>q.status==='Active').length;$('#top-time').textContent=`FIRST THAW · DAY ${state.day} · ${['DAWN','MORNING','MIDDAY','AFTERNOON','DUSK'][state.time-1]}`;$('#pulse-title').textContent=state.pulse||'The realm stirs';$('#pulse-copy').textContent=state.pulseCopy||'The Marches wait to see what you do.'}
function openPanel(panel){if(!state.hero&&panel==='character'){toast('Create your character to view the sheet.');return}let title='',sub='',html='';if(panel==='character'){title='Character sheet';sub=`Level ${state.hero.level} ${state.hero.ancestry} ${state.hero.class} · ${state.hero.background}`;html=`<div class="sheet-grid">${Object.entries(state.hero.attrs).map(([k,v])=>`<div class="sheet-stat"><small>${k} · ${attrName(k)}</small><strong>${v} <span style="font-size:11px;color:#a6ac9c">(${mod(v)>=0?'+':''}${mod(v)})</span></strong></div>`).join('')}</div><div class="sheet-block"><small>VITALS & PROGRESSION</small><p>HP ${state.hp}/${state.maxHp} · AC ${state.hero.class==='Fighter'||state.hero.class==='Cleric'?16:13} · Initiative ${mod(state.hero.attrs.DEX)>=0?'+':''}${mod(state.hero.attrs.DEX)} · Speed 30 ft<br>Level ${state.hero.level} · ${state.xp}/300 XP · Proficiency +2 · ${state.gold} gp</p></div><div class="sheet-block"><small>PERSONALITY & SETTING</small><p>${esc(state.hero.personality)} · ${esc(state.hero.difficulty)} difficulty · ${esc(state.hero.campaign)} · ${esc(state.hero.party)}</p></div><div class="sheet-block"><small>CLASS FEATURES</small><p>${classFeature(state.hero.class)}</p></div>`}
 else if(panel==='inventory'){title='Inventory';sub=`${state.gold} gold pieces · carried equipment`;html=`<ul class="modal-list">${state.inventory.map(x=>`<li>${esc(x)}<small>Carried · Common</small></li>`).join('')}</ul><div class="sheet-block"><small>CURRENCY</small><p>${state.gold} gp · Prices depend on the region and merchant.</p></div>`}
