2: const steps=[
3:  {key:'name',title:'What is your name?',help:'Every road begins with someone choosing to take it. What should the world call you?',type:'text',placeholder:'Your character’s name'},
4:  {key:'ancestry',title:'What is your ancestry?',help:'Ancestry shapes how others see you—and how you see the world.',options:[['Human','Adaptable, ambitious, and at home almost anywhere.'],['Elf','Long-lived, keen-sensed, and attuned to old magic.'],['Dwarf','Stout, steadfast, and raised among stone or steel.'],['Halfling','Small, resourceful, and often luckier than they ought to be.'],['Orc-blooded','Powerful, resilient, and never easily underestimated.'],['Tiefling','Marked by an ancient infernal legacy; no two marks alike.']]},
5:  {key:'class',title:'What path have you mastered?',help:'Your class describes training and talents, not who you must become.',options:[['Fighter','A disciplined warrior; reliable with weapons and armor.'],['Rogue','A scout and opportunist; excels at stealth and precision.'],['Wizard','A scholar of arcane magic; powerful, but prepared spells are limited.'],['Cleric','A divine conduit; protective magic and martial resolve.'],['Ranger','A hunter of wild places; survivalist and ranged combatant.'],['Bard','A versatile performer; words, wit, and a touch of magic.']]},
6:  {key:'background',title:'Where did you come from?',help:'Your former life leaves contacts, instincts, and unfinished business.',options:[['Wayfarer','You know how to find shelter where maps end.'],['Soldier','You served under a banner—and remember what it cost.'],['Scholar','You spent years among books, relics, or forbidden questions.'],['Outlander','The wilderness raised you more than any town did.'],['Artisan','You learned a craft whose value travels farther than you.'],['Criminal','You know the quiet doors and the price of silence.']]},
7:  {key:'personality',title:'What guides your choices?',help:'A compass, not a cage. Your outlook can change as the world presses in.',options:[['Kind-hearted','You look for the person behind the problem.'],['Pragmatic','You weigh consequences before ideals.'],['Curious','A mystery left unopened feels like a dare.'],['Defiant','You resist being told what cannot be done.'],['Reserved','Trust is earned, and silence has its uses.'],['Idealistic','You believe the world can be better—and act accordingly.']]},
8:  {key:'difficulty',title:'How dangerous should the road be?',help:'This adjusts encounter pressure, resource scarcity, and consequences.',options:[['Story','Forgiving danger; narrative and discovery take the lead.'],['Adventurer','Balanced exploration, tactical choices, and risk.'],['Veteran','Harder foes, scarce supplies, and sharper consequences.'],['Hardcore','Severe danger. Death is permanent; no safety net.']]},
9:  {key:'party',title:'Will you walk alone?',help:'Companions have their own opinions, loyalties, and limits.',options:[['Solo','One set of footsteps. All decisions—and dangers—are yours.'],['With companions','Potential allies can join as the story unfolds.'],['Open to either','Begin alone; let the road decide who joins you.']]},
10:  {key:'campaign',title:'What kind of story calls to you?',help:'The world is open. This sets its tone, not its boundaries.',options:[['Classic high fantasy','Ancient wonders, wild frontiers, and legendary creatures.'],['Dark fantasy','Beauty and horror share the same shadow.'],['Political intrigue','Promises, rival houses, and power that changes hands.'],['Open-world sandbox','Choose your own ambitions in a living realm.'],['Dungeons & treasure','Lost places, hard choices, and things better left buried.'],['Wilderness survival','The land is magnificent, indifferent, and unforgiving.'],['Kingdom building','Start small; decide what—and whom—you will rule.'],['A world unknown','A newly generated blend shaped by your choices.']]}
