12: const state={step:0,answers:{},hero:null,started:false,location:'The Unwritten Road',node:'road',time:1,day:1,weather:'Low clouds, a wind from the west',gold:18,xp:0,hp:0,maxHp:0,quests:[],log:[],inventory:[],companions:[],factions:{},visited:['The Unwritten Road'],combat:null};
13: const scenes={road:{name:'The Unwritten Road',detail:'The Shattered Marches · Frontier',title:'Where the old road ends',eyebrow:'THE SHATTERED MARCHES',body:'The road is a pale scar through the heather, its old paving stones split by roots. Somewhere beyond the ridge, a bell rings once—then falls quiet. A weather-beaten milestone points north to Morrowfen and east toward the distant black teeth of the Ashen Crown.\n\nAt the roadside, a handcart has tipped into a ditch. Its owner, a broad-shouldered woman in a moss-green cloak, is trying to free one wheel before the rain arrives. She glances up as you approach, measuring you without quite deciding what she sees.',choices:[['Offer to help with the cart','A small kindness may earn a little trust.','help'],['Ask about the bell','Find out who—or what—rang it.','bell'],['Continue toward Morrowfen','A village lies north, beneath the rain-heavy sky.','village'],['Inspect the milestone','The old carvings may reveal more than directions.','stone']]},
14:  village:{name:'Morrowfen',detail:'The Shattered Marches · Hamlet',title:'A town holding its breath',eyebrow:'MORROWFEN · NORTH ROAD',body:'Morrowfen gathers around a millpond the color of pewter. Smoke lies low over thatched roofs. Nobody has barred the road, but the people you pass stop speaking as you draw near. At the well, a child turns a little silver bell over in her hands; it is wrapped in blue thread.\n\nThe cart-woman’s name is Sella Venn. She mentioned her brother went looking for the source of the bell and did not return. The inn glows amber at the end of the lane; across from it, a shuttered shrine bears a fresh mark in chalk.',choices:[['Speak with Sella at the inn','She may know more about her brother.','sella'],['Ask the child about the silver bell','The child watches you from beside the well.','child'],['Examine the shuttered shrine','The chalk mark is recent.','shrine'],['Leave town and follow the northern trail','The trail bends toward a stand of dark pines.','trail']]},
15:  forest:{name:'Bellweather Wood',detail:'North of Morrowfen · Old forest',title:'A silence between the trees',eyebrow:'BELLWEATHER WOOD',body:'The pines crowd close enough to swallow the sky. A narrow trail descends into a damp hollow, where scraps of blue thread snag on the thorns. Near a leaning stone, you find a boot-print pressed into the mud beside a fresh set of claw marks. Whatever made them was heavy—and moving quickly.\n\nA faint metallic chime comes from deeper in the wood. In the silence after it, something shifts behind the trees.',choices:[['Follow the chime carefully','Stay alert; the ground is slick with roots.','chime'],['Track the boot-prints','The tracks may lead to Sella’s missing brother.','tracks'],['Return to Morrowfen','The village is safer, for now.','village']]},
16:  ruin:{name:'The Bell Vault',detail:'Bellweather Wood · Ruined shrine',title:'The sound beneath the stone',eyebrow:'A PLACE LEFT OFF THE MAP',body:'A half-buried stair descends beneath a ruin clasped in ivy. The air below is warmer than the rain above, carrying the scent of beeswax and something sharp, like struck flint. A bronze bell hangs in a narrow chamber—but its clapper has been removed. Blue thread is tied around its handle.\n\nA figure stands in the far archway, one hand raised to shield a lantern. “If you came for the bell,” they say, “you’re already late.”',choices:[['Ask who they are','A calm voice may reveal more than a drawn blade.','talk'],['Study the bell and chamber','Look for a mechanism or signs of magic.','inspect'],['Approach the figure cautiously','You can close the distance without drawing a weapon.','approach'],['Retreat into the wood','Some answers can wait.','forest']]}};
17: const line=(text)=>{state.log.unshift(text);state.log=state.log.slice(0,30)};
18: function renderStep(){const s=steps[state.step],card=$('#creation-card');card.innerHTML=`<div class="step-top"><span class="step-caption">CHARACTER CREATION</span><span class="step-index">${String(state.step+1).padStart(2,'0')} / ${steps.length}</span></div><div class="step-track">${steps.map((_,i)=>`<i class="${i<=state.step?'done':''}"></i>`).join('')}</div><h2>${s.title}</h2><p class="step-help">${s.help}</p><div id="step-content"></div><div class="step-controls">${state.step?'<button class="back-btn" id="back-btn">← Back</button>':'<span></span>'}<button class="next-btn" id="next-btn">${state.step===steps.length-1?'Create character':'Continue →'}</button></div>`;
19:  const content=$('#step-content'); if(s.type==='text'){content.innerHTML=`<label class="field-label" for="step-input">NAME</label><input id="step-input" class="text-field" maxlength="24" placeholder="${s.placeholder}" value="${esc(state.answers[s.key]||'')}" autofocus>`;$('#step-input').addEventListener('input',e=>state.answers[s.key]=e.target.value.trim())} else {content.innerHTML=`<div class="choice-grid">${s.options.map(([name,desc])=>`<label class="option-card ${state.answers[s.key]===name?'selected':''}"><input type="radio" name="choice" value="${esc(name)}" ${state.answers[s.key]===name?'checked':''}><b>${esc(name)}</b><small>${esc(desc)}</small></label>`).join('')}</div>`;$$('.option-card').forEach(el=>el.addEventListener('click',()=>{$$('.option-card').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');state.answers[s.key]=el.querySelector('input').value}))}
20:  $('#next-btn').onclick=()=>{if(!state.answers[s.key]){toast(s.type==='text'?'Please enter a name to continue.':'Choose an option to continue.');return}if(state.step<steps.length-1){state.step++;renderStep()}else createHero()};if(state.step)$('#back-btn').onclick=()=>{state.step--;renderStep()};if(s.type==='text')$('#step-input').focus();}
21: function createHero(){const a=state.answers, classBase={Fighter:[12,10,12,8,10,10],Rogue:[8,14,10,10,12,12],Wizard:[8,12,10,14,12,10],Cleric:[12,8,12,10,14,10],Ranger:[10,14,12,10,14,8],Bard:[8,12,10,12,10,14]}[a.class]||[10,10,10,10,10,10];const labels=['STR','DEX','CON','INT','WIS','CHA'];const attrs={};labels.forEach((k,i)=>attrs[k]=classBase[i]);state.hero={name:a.name,ancestry:a.ancestry,class:a.class,background:a.background,personality:a.personality,difficulty:a.difficulty,party:a.party,campaign:a.campaign,attrs,level:1,proficiency:2};state.maxHp=({Fighter:12,Rogue:10,Wizard:8,Cleric:10,Ranger:11,Bard:9}[a.class]||10)+Math.floor((attrs.CON-10)/2);state.hp=state.maxHp;state.gold=18;state.inventory=[a.class==='Fighter'?'Iron longsword':a.class==='Rogue'?'Hunting bow':a.class==='Wizard'?'Ash wand':a.class==='Cleric'?'Oak mace':a.class==='Ranger'?'Recurve bow':'Traveling lute','Worn leather armor','Rations ×2','Waterskin'];state.step=8;renderConfirm();updateUI()}
22: function renderConfirm(){const h=state.hero,c=$('#creation-card');$('#scene-title').innerHTML='A name takes shape.<br><em>The road can wait.</em>';$('#scene-eyebrow').textContent='CHARACTER READY';$('#story-body').innerHTML=`<p class="lead">${esc(h.name)}. A name the road has not heard before.</p><p>In the Shattered Marches, names are carried on wind and rumor. Yours begins with a past, a chosen path, and no promise of what comes next. The world is ready; the first adventure will begin only when you confirm your character.</p>`;c.innerHTML=`<div class="step-top"><span class="step-caption">YOUR CHARACTER</span><span class="step-index">LEVEL 1 · ${esc(h.class.toUpperCase())}</span></div><h2>${esc(h.name)}, ${esc(h.ancestry)} ${esc(h.class)}</h2><p class="step-help">${esc(h.background)} · ${esc(h.personality)} · ${esc(h.difficulty)} difficulty · ${esc(h.campaign)}</p><div class="attribute-row" style="padding:12px 0;border-top:1px solid #303830">${Object.entries(h.attrs).map(([k,v])=>`<span><b>${k}</b>${v} (${mod(v)})</span>`).join('')}</div><div class="step-controls"><button class="back-btn" id="edit-hero">← Edit character</button><button class="next-btn" id="confirm-hero">Confirm & begin adventure →</button></div>`;$('#edit-hero').onclick=()=>{state.step=7;renderStep()};$('#confirm-hero').onclick=beginAdventure;}
23: function beginAdventure(){state.started=true;state.node='road';state.location='The Unwritten Road';state.quests=[{name:'The Silent Bell',description:'Discover why a bell rang beyond the ridge—and what happened to Sella Venn’s brother.',status:'Active'}];line('The journey began on the Unwritten Road.');$('#creation-card').classList.add('hidden');$('#story-body').innerHTML='';showScene('road');updateUI();toast('Your campaign has begun. Good luck, '+state.hero.name+'.')}
24: function showScene(id,custom){state.node=id;const s=scenes[id]||scenes.road;state.location=s.name;$('#scene-eyebrow').textContent=s.eyebrow;$('#scene-title').textContent=s.title;$('#top-location').textContent=s.name.toUpperCase();$('#location-name').textContent=s.name;$('#map-current').textContent=s.name;$('#location-detail').textContent=s.detail;$('#story-body').innerHTML=(custom||s.body).split('\n\n').map((p,i)=>`<p ${i===0?'class="lead"':''}>${esc(p)}</p>`).join('');const box=$('#decision-area');box.classList.remove('hidden');$('#choice-list').innerHTML=s.choices.map(([title,desc,act],i)=>`<button class="story-choice" data-act="${act}"><span class="choice-marker">${String.fromCharCode(65+i)}</span><span><strong>${esc(title)}</strong><small>${esc(desc)}</small></span></button>`).join('');$$('.story-choice').forEach(b=>b.onclick=()=>act(b.dataset.act));if(!state.visited.includes(s.name))state.visited.push(s.name);updateUI()}
25: function rollCheck(skill,ability,dc,bonus=0){const raw=Math.floor(Math.random()*20)+1, modv=Math.floor((state.hero.attrs[ability]-10)/2), total=raw+modv+bonus;return {raw,modv,bonus,total,dc,success:total>=dc,skill}}
26: function rollText(r){return `${r.skill}: d20 (${r.raw}) ${r.modv>=0?'+':''}${r.modv} ability ${r.bonus?`+ ${r.bonus} proficiency`:''} = ${r.total} vs DC ${r.dc} · ${r.success?'Success':'Failure'} (pseudorandom)`}
